<script setup lang="ts">
import {computed,ref,watch,onMounted,onBeforeUnmount} from 'vue';import {useRoute} from 'vue-router';
import ModalDialog from './ModalDialog.vue';import {extraMessage,type SystemMessage} from '../lib/messages';
const route=useRoute(),messages=ref<SystemMessage[]>([]),open=ref(false);let observer:MutationObserver|undefined,frame=0,fingerprint='';
function sync(){frame=0;const list:SystemMessage[]=[];for(const node of document.querySelectorAll<HTMLElement>('.alert.error,.alert.warning,.alert.success,.text-danger[role="alert"]')){if(node.closest('.message-area,.message-details')||!node.getClientRects().length)continue;const kind=node.classList.contains('warning')?'W':node.classList.contains('success')?'S':'E',entries=node.matches('.alert.error')&&node.querySelector('li')?Array.from(node.querySelectorAll<HTMLElement>('li')):[node];for(const entry of entries){const text=entry.textContent?.trim().replace(/\s+/g,' ');if(text&&!list.some(m=>m.kind===kind&&m.text===text))list.push({kind,text,source:entry});}}
 list.sort((a,b)=>'EWSI'.indexOf(a.kind)-'EWSI'.indexOf(b.kind));const key=JSON.stringify(list.map(({kind,text})=>({kind,text})));if(key!==fingerprint||list.some((m,i)=>m.source!==messages.value[i]?.source)){fingerprint=key;messages.value=list;}}
function schedule(){if(!frame)frame=requestAnimationFrame(sync);}
function corrected(event:Event){if(extraMessage.value?.source===event.target&&(event.target as HTMLInputElement).validity?.valid)extraMessage.value=null;}
function invalid(event:Event){const input=event.target as HTMLInputElement;if(input.matches('input,select,textarea')){const label=input.labels?.[0]?.querySelector('.field-caption')?.textContent??input.getAttribute('aria-label')??'字段';extraMessage.value={kind:'E',text:label+'：'+input.validationMessage,source:input};}}
const all=computed(()=>[...messages.value,...(extraMessage.value?[extraMessage.value]:[])].sort((a,b)=>'EWSI'.indexOf(a.kind)-'EWSI'.indexOf(b.kind))),errors=computed(()=>all.value.filter(m=>m.kind==='E').length),warnings=computed(()=>all.value.filter(m=>m.kind==='W').length),current=computed(()=>all.value[0]);
function focus(message:SystemMessage){open.value=false;requestAnimationFrame(()=>{const node=message.source;if(!node?.isConnected)return;const anchor=node.querySelector<HTMLAnchorElement>('a[href="#"]');if(anchor){anchor.click();return;}const target=node.matches('input,select,textarea')?node:node.querySelector<HTMLElement>('input,select,textarea')??node;target.scrollIntoView({block:'center'});if(!target.hasAttribute('tabindex')&&!target.matches('input,select,textarea'))target.setAttribute('tabindex','-1');target.focus();});}
watch(()=>route.fullPath,()=>{extraMessage.value=null;open.value=false;fingerprint='';schedule();});
onMounted(()=>{observer=new MutationObserver(schedule);observer.observe(document.body,{subtree:true,childList:true,characterData:true,attributes:true,attributeFilter:['class','aria-invalid','open','hidden']});document.addEventListener('invalid',invalid,true);document.addEventListener('input',corrected,true);sync();});onBeforeUnmount(()=>{observer?.disconnect();cancelAnimationFrame(frame);document.removeEventListener('invalid',invalid,true);document.removeEventListener('input',corrected,true);});
</script>
<template><aside class="message-area" aria-label="系统消息"><button type="button" class="message-summary" :aria-expanded="open" @click="open=!open"><span class="message-code" :class="'message-'+(current?.kind??'I')">{{ current?.kind??'I' }}</span><span class="message-copy"><strong>{{ current?.text??'当前没有错误或警告' }}</strong><small><span class="count-e">E {{ errors }}</span> · <span class="count-w">W {{ warnings }}</span> · {{ all.length?'查看消息':'提交时检查必填项' }}</small></span></button><span class="sr-only" role="status" aria-live="polite" aria-atomic="true">{{ current?.kind }} {{ current?.text }}</span></aside><ModalDialog v-if="open" title="系统消息" @close="open=false"><div class="message-details"><p v-if="!all.length">当前没有错误或警告。表单必填项会在检查或提交时验证。</p><article v-for="(message,index) in all" :key="index"><span class="message-code" :class="'message-'+message.kind">{{ message.kind }}</span><div><p>{{ message.text }}</p><button v-if="message.source?.isConnected" type="button" @click="focus(message)">定位消息</button></div></article><button type="button" @click="open=false">关闭消息</button></div></ModalDialog></template>
<style scoped>
.message-area{position:fixed;left:12px;bottom:max(12px,env(safe-area-inset-bottom));width:204px;z-index:35}.message-summary{width:100%;display:flex;align-items:center;gap:10px;padding:10px 12px;text-align:left;white-space:normal;background:var(--paper);border:1px solid #cfbeb1;border-radius:10px;box-shadow:0 3px 15px #493e401a}.message-code{font:700 16px/1.4 ui-monospace,monospace;display:grid;place-items:center;width:28px;height:28px;flex-shrink:0;border:1px solid;border-radius:5px}.message-E{color:#a32028;background:#fde8e9;border-color:#ca7880}.message-W{color:#755300;background:#ffe6a0;border-color:#c3982b}.message-S{color:#276844;background:#e6f3e9;border-color:#8eb59b}.message-I{color:#466276;background:#e7eef2;border-color:#a9bdcb}.message-copy{min-width:0}.message-copy strong{display:-webkit-box;-webkit-line-clamp:2;-webkit-box-orient:vertical;overflow:hidden;font-size:12px;font-weight:500;line-height:1.6;overflow-wrap:anywhere}.message-copy small{font-size:11px;margin-top:4px}.count-e{color:#a32028}.count-w{color:#755300}.message-details article{display:flex;align-items:flex-start;gap:12px;border-bottom:1px solid var(--line);padding:12px 0;margin-bottom:12px}.message-details p{overflow-wrap:anywhere;margin-bottom:8px}@media(max-width:1100px) and (min-width:761px){.message-area{width:166px}}@media(max-width:760px){.message-area{width:calc(100% - 24px)}.message-copy strong{font-size:13px}.message-copy small{font-size:12px}.message-summary{min-height:64px}}@media print{.message-area{display:none}}
</style>
